package com.bidx.servlet;import jakarta.servlet.http.*;import jakarta.servlet.*;import java.io.*;import com.bidx.model.*;
public abstract class BaseServlet extends HttpServlet {protected User user(HttpServletRequest r){return (User)r.getSession().getAttribute("user");}protected void view(HttpServletRequest r,HttpServletResponse p,String path)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/"+path+".jsp").forward(r,p);}protected void flash(HttpServletRequest r,String msg,String type){r.getSession().setAttribute("flash",msg);r.getSession().setAttribute("flashType",type);}}
